#include <bits/stdc++.h>
using namespace std;
int main(){
    vector<string> dict;
    string line;
    while (getline(cin, line)) {
        if (line.empty()) break;
        dict.push_back(line);
    }
    int n = dict.size();
    unordered_map<string,int> idx;
    for (int i=0;i<n;i++) idx[dict[i]] = i;
    unordered_map<string, vector<int>> buckets;
    for (int i=0;i<n;i++){
        string w = dict[i];
        for (size_t k=0;k<w.size();k++){
            string pat = w;
            pat[k] = '*';
            buckets[pat].push_back(i);
        }
    }
    string a,b;
    bool first = true;
    while (cin >> a >> b) {
        if (!first) cout << "\n";
        first = false;
        if (idx.find(a)==idx.end() || idx.find(b)==idx.end()) {
            cout << "No solution.\n";
            continue;
        }
        int s = idx[a], t = idx[b];
        vector<int> prev(n, -2);
        prev[s] = -1;
        queue<int> q;
        q.push(s);
        bool found = (s==t);
        while (!q.empty() && !found) {
            int u = q.front(); q.pop();
            string w = dict[u];
            for (size_t k=0;k<w.size() && !found;k++){
                string pat = w;
                pat[k] = '*';
                auto it = buckets.find(pat);
                if (it==buckets.end()) continue;
                for (int v : it->second) {
                    if (prev[v]==-2) {
                        prev[v]=u;
                        if (v==t) { found=true; break; }
                        q.push(v);
                    }
                }
            }
        }
        if (prev[t]==-2 && s!=t) {
            cout << "No solution.\n";
        } else {
            vector<int> path;
            int cur = t;
            while (cur != -1) { path.push_back(cur); cur = prev[cur]; }
            reverse(path.begin(), path.end());
            for (int id2 : path) cout << dict[id2] << "\n";
        }
    }
}

